option.value:
extends ../templates/page

include ../components/block
include ../components/component

block append head
    link(rel="stylesheet" href=`/assets/public/dist/pages/reponse/reponse.min.css?t=${Math.random()}`)
    // styles moved to assets/src/pages/reponse/reponse.r.less and compiled to assets/public/dist/pages/reponse/reponse.min.css
    // immediate inline overrides for closed-note and disabled composer (visitor side)
    style.
        .composer-wrap.disabled{ opacity:0.6; }
        .composer-wrap.disabled textarea{ background:#f3f4f6; cursor:not-allowed; }
        .composer-wrap.disabled .send-btn{ cursor:not-allowed; opacity:0.6; }
        .composer-wrap.disabled .attachment-btn, .composer-wrap.disabled .attachment-btn .fi{ pointer-events:none; cursor:not-allowed; opacity:0.6; }
        .composer-wrap .closed-note{ margin-bottom:8px; background:#fff6f6; color:#b91c1c; padding:8px 10px; border-radius:8px; font-size:13px; font-weight:600; border:1px solid rgba(185,28,28,0.08); }

block append body
    .response-page(data-assist-id=(assist && assist.id ? assist.id : (typeof assistId !== 'undefined' ? assistId : '')) data-backend=(backend || '') data-reponses-fetched=(typeof reponses_fetched !== 'undefined' && reponses_fetched ? '1' : '0') data-assist-closed=(assistClosed ? '1' : '0'))
        .container
            .content
                .chat-panel
                    .discussion-card
                        h2.section-title Discussion
                        if typeof reponses_fetched !== 'undefined' && !reponses_fetched
                            .server-warning&attributes({ 'style': "margin-bottom:10px; padding:8px 12px; background:#fff3cd; border:1px solid #ffeeba; border-radius:6px; color:#856404;" })
                                | Le serveur n'a pas chargé les réponses — tentative de chargement côté client en cours...

                        - // statut variables (used both in header and side-panel)
                        - var statutCode = (assist && (assist.statut || assist.status)) ? String(assist.statut || assist.status).replace(/\s+/g,'_').toLowerCase() : 'en_attente'
                        - var statutLabel = (assist && (assist.statut_label || assist.statut || assist.status_label || assist.status)) ? (assist.statut_label || assist.statut || assist.status_label || assist.status) : 'En attente'
                        - // server-side detection whether the assistance is closed (so composer is pre-disabled)
                        - var _rawStatus = ''
                        - if(assist){ _rawStatus = String(assist.statut || assist.status || assist.statut_label || assist.status_label || ''); }
                        - try { _rawStatus = _rawStatus && _rawStatus.normalize ? _rawStatus.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase() : String(_rawStatus).toLowerCase(); } catch(e) { _rawStatus = String(_rawStatus).toLowerCase(); }
                        - var _closedKeywords = ['termine','terminee','terminé','terminée','refuse','refusee','refus','refusée','cloturee','cloture','clos','closed','rejet','annulee','annule','rejected']
                        - var assistClosed = _closedKeywords.some(function(k){ return (_rawStatus||'').indexOf(k) !== -1; });

                        // header: service title, author, date, status badge (remove raw ID display)
                        .response-info(style="margin-bottom:12px;")
                            h1#serviceTitle.service-title(style="margin:0 0 6px; font-size:1.25rem; color:rgba(11,20,44,0.9);") #{assist && (assist.service ? (assist.service + (assist.domaine ? ' - ' + assist.domaine : '')) : (assist.subject || 'Demande'))}
                            .submeta(style="display:flex; gap:12px; align-items:center; color:rgba(11,20,44,0.7); font-size:0.95rem;")
                                if assist && (assist.nom || assist.prenom || assist.user_name)
                                    span#headerAuthor.author
                                        span.fi.fi-rr-user
                                        |  #{assist.nom ? (assist.nom + (assist.prenom ? ' ' + assist.prenom : '')) : (assist.user_name || '')}
                                if assist && (assist.created_at || assist.createdAt)
                                    span#headerDate.date
                                        span.fi.fi-rr-calendar
                                        |  #{assist.created_at ? (new Date(assist.created_at).toLocaleDateString()) : (assist.createdAt ? (new Date(assist.createdAt).toLocaleDateString()) : '')}
                                // status badge inline in header
                                span
                                    span#headerStatusBadge(class=`status-badge status-${statutCode}`) #{statutLabel}

                            // HTML debug comment to show server-side status values in the rendered page source
                            | <!-- DEBUG assist.statut=#{assist && (assist.statut || '')} assist.status=#{assist && (assist.status || '')} assistClosed=#{assistClosed} -->

                        .messages#messages
                            // messages will be rendered server-side too: initial assist + reponses_list
                            if assist
                                - var assistDate = assist.created_at ? (new Date(assist.created_at)).toLocaleString() : ''
                                - var initialClass = 'message message-visiteur'
                                div&attributes({ 'class': initialClass })
                                    .meta
                                        span.author #{assist.nom ? (assist.nom + (assist.prenom ? ' ' + assist.prenom : '')) : (assist.user_name || 'Visiteur')}
                                        span.date #{assistDate}
                                    .body
                                        | #{assist.message || ''}
                                    if assist.attachments && assist.attachments.length
                                        .attachments
                                            each a in assist.attachments
                                                - var fileUrlA = a.file_url || a.url || a.path || ''
                                                - var hrefA = ''
                                                - // Prefer direct backend static URL for uploads (no auth) when possible
                                                - if(fileUrlA && fileUrlA.indexOf('/uploads') === 0) hrefA = (backend? backend.replace(/\/$/,'') + fileUrlA : fileUrlA)
                                                - else if(fileUrlA && /^https?:\/\//.test(fileUrlA)) hrefA = fileUrlA
                                                - else if(a.id) hrefA = '/assistances/' + (assist && assist.id ? assist.id : '') + '/reponses/attachments/' + a.id
                                                - else hrefA = (fileUrlA || '#')
                                                a.attachment(href=hrefA target="_blank" download data-download="1")
                                                    span.file-icon
                                                        span(class='fi fi-rr-file')
                                                    span.attachment-name #{a.filename || a.originalname || a.name || (fileUrlA? fileUrlA.split('/').pop() : '') || 'Pièce jointe'}
                                                    span.attachment-download
                                                        span(class='fi fi-rr-download')

                            if reponses_list && reponses_list.length
                                each r in reponses_list
                                    - var role = (r.role || '').toString().toLowerCase();
                                    - var cls = (/admin|accomp/).test(role) ? 'message-admin' : 'message-visiteur';
                                    - var author = r.author_name || (r.user_first_name ? (r.user_first_name + ' ' + (r.user_last_name||'')) : (r.user_name || r.author || ''));
                                    - var dateR = r.created_at ? (new Date(r.created_at)).toLocaleString() : '';
                                    - var fullClass = 'message ' + cls
                                    div&attributes({ 'class': fullClass })
                                        .meta
                                            span.author #{author}
                                            span.date #{dateR}
                                        .body
                                            | #{r.content || r.message || r.body || r.text || ''}
                                        - var attachments = r.attachments || r.files || r.pieces || r.documents || []
                                        if attachments && attachments.length
                                            .attachments
                                                each a in attachments
                                                    - var fileUrl = a.file_url || a.url || a.path || ''
                                                    - var hrefR = ''
                                                    - if(fileUrl && fileUrl.indexOf('/uploads') === 0) hrefR = (backend? backend.replace(/\/$/,'') + fileUrl : fileUrl)
                                                    - else if(fileUrl && /^https?:\/\//.test(fileUrl)) hrefR = fileUrl
                                                    - else if(a.id) hrefR = '/assistances/' + (assist && assist.id ? assist.id : '') + '/reponses/attachments/' + a.id
                                                    - else hrefR = (fileUrl || '#')
                                                    a.attachment(href=hrefR target="_blank" download data-download="1")
                                                        span.file-icon
                                                            span(class='fi fi-rr-file')
                                                        span.attachment-name #{a.filename || a.originalname || a.name || (fileUrl? fileUrl.split('/').pop() : '') || 'Pièce jointe'}
                                                        span.attachment-download
                                                            span(class='fi fi-rr-download')
                        // end messages

                        .composer-wrap(class=(assistClosed ? 'disabled' : ''), style="display:block;")
                            .selected-files#selectedFiles(style=(assistClosed ? "display:none;" : "display:block;"))
                            if assistClosed
                                .closed-note Assistance clôturée. Vous ne pouvez plus répondre.

                            // form: keep textarea flexible and actions on same line without wrapping
                            form#replyForm(enctype="multipart/form-data" style="display:flex; gap:8px; align-items:center; flex-wrap:nowrap;")
                                - var taStyle = assistClosed ? "flex:1 1 auto; min-height:48px; margin:0; background:#f3f4f6; cursor:not-allowed; color:rgba(0,0,0,0.65); min-width:0;" : "flex:1 1 auto; min-height:48px; margin:0; min-width:0;"
                                textarea#replyContent(name="content" rows="3" placeholder="Écrivez votre message..." style=taStyle disabled=assistClosed)
                                .composer-actions(style="display:flex; gap:8px; align-items:center; flex:0 0 auto; white-space:nowrap;")
                                    - var attachStyle = assistClosed ? 'display:inline-flex; align-items:center; justify-content:center; cursor:not-allowed; padding:6px; border-radius:8px; border:1px solid rgba(11,20,44,0.06); background:#fff; pointer-events:none; opacity:0.6;' : 'display:inline-flex; align-items:center; justify-content:center; cursor:pointer; padding:6px; border-radius:8px; border:1px solid rgba(11,20,44,0.06); background:#fff;'
                                    label.attachment-btn(class=(assistClosed ? 'disabled' : ''), style=attachStyle)
                                        input(type="file" id="attachmentInput" name="attachments" multiple disabled=assistClosed)
                                        span.fi.fi-rr-clip
                                    - var sendStyle = assistClosed ? 'display:inline-flex; align-items:center; padding:8px 12px; border-radius:8px; background:#1E88E5; color:#fff; border:none; opacity:0.6; cursor:not-allowed; pointer-events:none;' : 'display:inline-flex; align-items:center; padding:8px 12px; border-radius:8px; background:#1E88E5; color:#fff; border:none;'
                                    button.send-btn(class=(assistClosed ? 'disabled' : ''), type="submit" style=sendStyle disabled=assistClosed)
                                        span.fi.fi-rr-paper-plane

                            // Immediate defensive script: ensure composer controls are disabled as soon as possible when server indicated closed (or header shows closed)
                            script.
                                (function(){
                                    try{
                                        var page = document.querySelector('.response-page'); if(!page) return;
                                        var assistClosedAttr = page.getAttribute('data-assist-closed') === '1';
                                        var badge = document.getElementById('headerStatusBadge') || document.querySelector('.status-badge');
                                        var badgeText = '';
                                        try{ badgeText = badge && badge.textContent ? (badge.textContent.normalize ? badge.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase() : badge.textContent.toLowerCase()) : ''; }catch(_){ badgeText = (badge && badge.textContent) ? String(badge.textContent).toLowerCase() : ''; }
                                        var closedKeywords = ['termine','terminee','terminé','terminée','refuse','refusee','refus','refusée','cloturee','cloture','clos','closed','rejet','annulee','annule','rejected'];
                                        var badgeIndicatesClosed = closedKeywords.some(function(k){ return (badgeText || '').indexOf(k) !== -1; });
                                        if(!assistClosedAttr && !badgeIndicatesClosed) return;
                                        var wrap = document.querySelector('.composer-wrap'); if(!wrap) return;
                                        try{ wrap.classList.add('disabled'); }catch(_){ }
                                        try{ var ta = wrap.querySelector('textarea#replyContent'); if(ta){ ta.disabled = true; ta.readOnly = true; ta.setAttribute('aria-disabled','true'); } }catch(_){ }
                                        try{ var fi = wrap.querySelector('#attachmentInput'); if(fi){ fi.disabled = true; fi.setAttribute('aria-disabled','true'); } }catch(_){ }
                                        try{ var sb = wrap.querySelector('button.send-btn'); if(sb){ sb.disabled = true; sb.setAttribute('aria-disabled','true'); sb.classList.add('disabled'); } }catch(_){ }
                                        if(!wrap.querySelector('.closed-note')){ var note = document.createElement('div'); note.className = 'closed-note'; note.textContent = 'Assistance clôturée. Vous ne pouvez plus répondre.'; var formEl = wrap.querySelector('form'); if(formEl) wrap.insertBefore(note, formEl); else wrap.appendChild(note); }
                                    }catch(e){ /* noop */ }
                                })();

                            // Client-side attachment preview/render (shows file chip above textarea)
                            script.
                                (function(){
                                    try{
                                        var fileInput = document.getElementById('attachmentInput');
                                        var selectedWrap = document.getElementById('selectedFiles');
                                        if(!fileInput || !selectedWrap) return;

                                        // DataTransfer to manage files so input.files can be mutated
                                        var dt = new DataTransfer();

                                        function renderChips(){
                                            selectedWrap.innerHTML = '';
                                            Array.from(dt.files).forEach(function(f, idx){
                                                var chip = document.createElement('div');
                                                chip.className = 'file-chip';
                                                chip.style.display = 'flex';
                                                chip.style.alignItems = 'center';
                                                chip.style.justifyContent = 'space-between';
                                                chip.style.gap = '12px';
                                                chip.style.padding = '8px 12px';
                                                chip.style.background = '#eef6ff';
                                                chip.style.borderRadius = '12px';

                                                var left = document.createElement('div');
                                                left.style.display = 'flex';
                                                left.style.alignItems = 'center';
                                                left.style.gap = '10px';

                                                var ico = document.createElement('span'); ico.className = 'file-icon'; ico.textContent = ''; ico.style.fontSize = '16px';
                                                var name = document.createElement('span'); name.className = 'file-name'; name.textContent = f.name; name.style.overflow = 'hidden'; name.style.textOverflow = 'ellipsis'; name.style.whiteSpace = 'nowrap'; name.style.maxWidth = '240px';
                                                left.appendChild(ico); left.appendChild(name);

                                                var actions = document.createElement('div'); actions.style.display = 'flex'; actions.style.alignItems = 'center'; actions.style.gap = '8px';

                                                var dl = document.createElement('a'); dl.className = 'attachment-download'; dl.textContent = '⬇️'; dl.href = '#'; dl.style.textDecoration = 'none'; dl.style.color = '#095ab5'; dl.style.fontSize = '16px'; dl.target = '_blank';
                                                try{
                                                    var blobUrl = URL.createObjectURL(f);
                                                    dl.href = blobUrl; dl.download = f.name;
                                                    dl.addEventListener('click', function(){ setTimeout(function(){ try{ URL.revokeObjectURL(blobUrl); }catch(_){ } }, 2000); });
                                                }catch(_){ }

                                                var removeBtn = document.createElement('button'); removeBtn.type = 'button'; removeBtn.className = 'file-remove'; removeBtn.textContent = '×'; removeBtn.style.background = 'none'; removeBtn.style.border = 'none'; removeBtn.style.color = '#095ab5'; removeBtn.style.cursor = 'pointer'; removeBtn.style.fontSize = '16px';
                                                removeBtn.addEventListener('click', function(){
                                                    var newDt = new DataTransfer();
                                                    Array.from(dt.files).forEach(function(ff, i){ if(i !== idx) newDt.items.add(ff); });
                                                    dt = newDt; fileInput.files = dt.files; renderChips();
                                                });

                                                actions.appendChild(dl); actions.appendChild(removeBtn);

                                                chip.appendChild(left); chip.appendChild(actions);
                                                selectedWrap.appendChild(chip);
                                            });

                                            selectedWrap.style.display = (dt.files && dt.files.length) ? 'block' : 'none';
                                        }

                                        fileInput.addEventListener('change', function(e){
                                            var incoming = Array.from(fileInput.files || []);
                                            incoming.forEach(function(f){
                                                var exists = Array.from(dt.files).some(function(x){ return x.name === f.name && x.size === f.size && x.lastModified === f.lastModified; });
                                                if(!exists) dt.items.add(f);
                                            });
                                            fileInput.files = dt.files; renderChips();
                                        });

                                        // keep chips in sync when form reset occurs
                                        var form = document.getElementById('replyForm');
                                        if(form){
                                            form.addEventListener('reset', function(){ dt = new DataTransfer(); fileInput.files = dt.files; renderChips(); });
                                        }

                                        // initial render (in case preloaded files exist)
                                        renderChips();
                                    }catch(e){ console.error('attachment preview init error', e); }
                                })();

                            // Intercept clicks on server-side attachment anchors and download via fetch with credentials
                            script.
                                (function(){
                                    try{
                                        document.addEventListener('click', function(ev){
                                            var a = ev.target.closest && ev.target.closest('.attachment');
                                            if(!a) return;
                                            var href = a.getAttribute('href') || '';
                                            // if href is a blob or local url (starts with blob: or data:) let browser handle it
                                            if(!href || href === '#' || href.indexOf('blob:') === 0 || href.indexOf('data:') === 0) return;
                                            // Only intercept backend proxied attachment endpoints or paths that look like /assistances/.../attachments/ or /uploads
                                            if(!(href.indexOf('/reponses/attachments/') !== -1 || href.indexOf('/assistances/') === 0 || href.indexOf('/uploads') === 0 || href.indexOf(location.origin) === 0)) return;
                                            ev.preventDefault();
                                            a.classList.add('attachment-loading');
                                            (async function(){
                                                try{
                                                    var resp = await fetch(href, { credentials: 'include' });
                                                    if(!resp.ok){
                                                        var txt = await resp.text().catch(function(){ return 'HTTP ' + resp.status; });
                                                        alert('Erreur téléchargement: ' + resp.status + '\n' + txt);
                                                        return;
                                                    }
                                                    var blob = await resp.blob();
                                                    var filename = (a.querySelector('.attachment-name') && a.querySelector('.attachment-name').textContent.trim()) || 'download';
                                                    try{
                                                        var cd = resp.headers.get('content-disposition');
                                                        if(cd){ var m = cd.match(/filename\*?=(?:UTF-8'')?"?([^;"']+)"?/i); if(m && m[1]) filename = decodeURIComponent(m[1]); }
                                                    }catch(_){ }
                                                    var blobUrl = URL.createObjectURL(blob);
                                                    var tmp = document.createElement('a'); tmp.href = blobUrl; tmp.download = filename; document.body.appendChild(tmp); tmp.click(); tmp.remove(); setTimeout(function(){ try{ URL.revokeObjectURL(blobUrl); }catch(_){ } }, 2000);
                                                }catch(e){ console.error('attachment download error', e); alert('Erreur réseau lors du téléchargement'); }
                                                finally{ try{ a.classList.remove('attachment-loading'); }catch(_){ } }
                                            })();
                                        });
                                    }catch(e){ console.error('attachment download interceptor init error', e); }
                                })();

                            // Intercept form submit and send message + attachments via fetch
                            script.
                                (function(){
                                    try{
                                        var page = document.querySelector('.response-page');
                                        var form = document.getElementById('replyForm');
                                        if(!page || !form) return;
                                        var assistId = page.getAttribute('data-assist-id') || '';
                                        form.addEventListener('submit', async function(ev){
                                            ev.preventDefault();
                                            try{
                                                var submitBtn = form.querySelector('button[type="submit"]');
                                                if(submitBtn) submitBtn.disabled = true;
                                                var ta = form.querySelector('textarea[name="content"]');
                                                var content = ta ? String(ta.value || '').trim() : '';
                                                var fileInput = form.querySelector('#attachmentInput');
                                                var hasFiles = fileInput && fileInput.files && fileInput.files.length;
                                                if(!content && !hasFiles){ alert('Veuillez saisir un message ou joindre un fichier.'); if(submitBtn) submitBtn.disabled = false; return; }

                                                var fd = new FormData();
                                                fd.append('content', content);
                                                if(fileInput && fileInput.files){
                                                    for(var i=0;i<fileInput.files.length;i++){ fd.append('attachments', fileInput.files[i]); }
                                                }
                                                // role for server: visitor
                                                fd.append('role', 'visiteur');

                                                var url = '/assistances/' + encodeURIComponent(assistId) + '/reponses';

                                                var resp = await fetch(url, { method: 'POST', body: fd, credentials: 'include' });
                                                if(!resp.ok){
                                                    var txt = '';
                                                    try{ txt = await resp.text(); }catch(_){ txt = String(resp.status); }
                                                    alert('Erreur envoi: ' + resp.status + '\n' + txt);
                                                    return;
                                                }

                                                // success: clear form & selected files preview and reload to get latest messages
                                                try{ form.reset(); }catch(_){ }
                                                try{ var evc = new Event('change'); var fi = form.querySelector('#attachmentInput'); if(fi) fi.dispatchEvent(evc); }catch(_){ }
                                                // reload to show the freshly posted message
                                                location.reload();
                                            }catch(e){ console.error('reply submit error', e); alert('Erreur réseau lors de l\'envoi'); }
                                            finally{ try{ var b = form.querySelector('button[type="submit"]'); if(b) b.disabled = false; }catch(_){ } }
                                        });
                                    }catch(e){ console.error('reply init error', e); }
                                })();

extends ../templates/page

include ../components/block
include ../components/component

block append head
    link(rel="stylesheet" href=`/assets/public/dist/pages/reponse/reponse.min.css?t=${Math.random()}`)
    // styles moved to assets/src/pages/reponse/reponse.r.less and compiled to assets/public/dist/pages/reponse/reponse.min.css
    // immediate inline overrides for closed-note and disabled composer (visitor side)
    style.
        .composer-wrap.disabled{ opacity:0.6; }
        .composer-wrap.disabled textarea{ background:#f3f4f6; cursor:not-allowed; }
        .composer-wrap.disabled .send-btn{ cursor:not-allowed; opacity:0.6; }
        .composer-wrap.disabled .attachment-btn, .composer-wrap.disabled .attachment-btn .fi{ pointer-events:none; cursor:not-allowed; opacity:0.6; }
        .composer-wrap .closed-note{ margin-bottom:8px; background:#fff6f6; color:#b91c1c; padding:8px 10px; border-radius:8px; font-size:13px; font-weight:600; border:1px solid rgba(185,28,28,0.08); }
        /* Grey-out composer when statut indicates final state (terminee/refusee) */
        /* Use attribute substring match to handle variations and accents normalized on server */
        .response-page[data-statut*="term"] .composer-wrap,
        .response-page[data-statut*="refus"] .composer-wrap {
            opacity: 0.6;
            pointer-events: none; /* visually and functionally disable interactions */
        }
        /* Also ensure the interactive controls inside appear disabled */
        .response-page[data-statut*="term"] .composer-wrap textarea,
        .response-page[data-statut*="refus"] .composer-wrap textarea,
        .response-page[data-statut*="term"] .composer-wrap input,
        .response-page[data-statut*="refus"] .composer-wrap input,
        .response-page[data-statut*="term"] .composer-wrap button,
        .response-page[data-statut*="refus"] .composer-wrap button {
            cursor: not-allowed;
            opacity: 0.9;
        }
        /* fallback: when client marks the page as final */
        .response-page.statut-final .composer-wrap { opacity:0.6; pointer-events:none; }
        .response-page.statut-final .composer-wrap textarea, .response-page.statut-final .composer-wrap input, .response-page.statut-final .composer-wrap button { cursor:not-allowed; }
        /* Also apply when server indicates the assistance is closed */
        .response-page[data-assist-closed="1"] .composer-wrap { opacity:0.6; pointer-events:none; }
        .response-page[data-assist-closed="1"] .composer-wrap textarea, .response-page[data-assist-closed="1"] .composer-wrap input, .response-page[data-assist-closed="1"] .composer-wrap button { cursor:not-allowed; }
        /* Ensure overlay becomes visible to block interactions when final */
        .response-page.statut-final .composer-overlay,
        .response-page[data-assist-closed="1"] .composer-overlay,
        .response-page[data-statut*="term"] .composer-overlay,
        .response-page[data-statut*="refus"] .composer-overlay { display:block; position:absolute; inset:0; z-index:50; pointer-events:auto; cursor:not-allowed; }

block append body
    .response-page(data-assist-id=(assist && assist.id ? assist.id : (typeof assistId !== 'undefined' ? assistId : '')) data-backend=(backend || '') data-reponses-fetched=(typeof reponses_fetched !== 'undefined' && reponses_fetched ? '1' : '0') data-assist-closed=(assistClosed ? '1' : '0') data-statut=statutCode)
        .container
            .content
                .chat-panel
                    .discussion-card
                        h2.section-title Discussion
                        if typeof reponses_fetched !== 'undefined' && !reponses_fetched
                            .server-warning&attributes({ 'style': "margin-bottom:10px; padding:8px 12px; background:#fff3cd; border:1px solid #ffeeba; border-radius:6px; color:#856404;" })
                                | Le serveur n'a pas chargé les réponses — tentative de chargement côté client en cours...

                        - // statut variables (used both in header and side-panel)
                        - var statutCode = (assist && (assist.statut || assist.status)) ? String(assist.statut || assist.status).replace(/\s+/g,'_').toLowerCase() : 'en_attente'
                        - var statutLabel = (assist && (assist.statut_label || assist.statut || assist.status_label || assist.status)) ? (assist.statut_label || assist.statut || assist.status_label || assist.status) : 'En attente'
                        - // server-side detection whether the assistance is closed (so composer is pre-disabled)
                        - var _rawStatus = ''
                        - if(assist){ _rawStatus = String(assist.statut || assist.status || assist.statut_label || assist.status_label || ''); }
                        - try { _rawStatus = _rawStatus && _rawStatus.normalize ? _rawStatus.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase() : String(_rawStatus).toLowerCase(); } catch(e) { _rawStatus = String(_rawStatus).toLowerCase(); }
                        - var _closedKeywords = ['termine','terminee','terminé','terminée','refuse','refusee','refus','refusée','cloturee','cloture','clos','closed','rejet','annulee','annule','rejected']
                        - var assistClosed = _closedKeywords.some(function(k){ return (_rawStatus||'').indexOf(k) !== -1; });

                        // header: service title, author, date, status badge (remove raw ID display)
                        .response-info(style="margin-bottom:12px;")
                            h1#serviceTitle.service-title(style="margin:0 0 6px; font-size:1.25rem; color:rgba(11,20,44,0.9);") #{assist && (assist.service ? (assist.service + (assist.domaine ? ' - ' + assist.domaine : '')) : (assist.subject || 'Demande'))}
                            .submeta(style="display:flex; gap:12px; align-items:center; color:rgba(11,20,44,0.7); font-size:0.95rem;")
                                if assist && (assist.nom || assist.prenom || assist.user_name)
                                    span#headerAuthor.author
                                        span.fi.fi-rr-user
                                        |  #{assist.nom ? (assist.nom + (assist.prenom ? ' ' + assist.prenom : '')) : (assist.user_name || '')}
                                if assist && (assist.created_at || assist.createdAt)
                                    span#headerDate.date
                                        span.fi.fi-rr-calendar
                                        |  #{assist.created_at ? (new Date(assist.created_at).toLocaleDateString()) : (assist.createdAt ? (new Date(assist.createdAt).toLocaleDateString()) : '')}
                                // status badge inline in header
                                span
                                    span#headerStatusBadge(class=`status-badge status-${statutCode}`) #{statutLabel}

                            // HTML debug comment to show server-side status values in the rendered page source
                            | <!-- DEBUG assist.statut=#{assist && (assist.statut || '')} assist.status=#{assist && (assist.status || '')} assistClosed=#{assistClosed} -->

                        .messages#messages
                            // messages will be rendered server-side too: initial assist + reponses_list
                            if assist
                                - var assistDate = assist.created_at ? (new Date(assist.created_at)).toLocaleString() : ''
                                - var initialClass = 'message message-visiteur'
                                div&attributes({ 'class': initialClass })
                                    .meta
                                        span.author #{assist.nom ? (assist.nom + (assist.prenom ? ' ' + assist.prenom : '')) : (assist.user_name || 'Visiteur')}
                                        span.date #{assistDate}
                                    .body
                                        | #{assist.message || ''}
                                    if assist.attachments && assist.attachments.length
                                        .attachments
                                            each a in assist.attachments
                                                - var fileUrlA = a.file_url || a.url || a.path || ''
                                                - var hrefA = ''
                                                - // Prefer direct backend static URL for uploads (no auth) when possible
                                                - if(fileUrlA && fileUrlA.indexOf('/uploads') === 0) hrefA = (backend? backend.replace(/\/$/,'') + fileUrlA : fileUrlA)
                                                - else if(fileUrlA && /^https?:\/\//.test(fileUrlA)) hrefA = fileUrlA
                                                - else if(a.id) hrefA = '/assistances/' + (assist && assist.id ? assist.id : '') + '/reponses/attachments/' + a.id
                                                - else hrefA = (fileUrlA || '#')
                                                a.attachment(href=hrefA target="_blank" download data-download="1")
                                                    span.file-icon
                                                        span(class='fi fi-rr-file')
                                                    span.attachment-name #{a.filename || a.originalname || a.name || (fileUrlA? fileUrlA.split('/').pop() : '') || 'Pièce jointe'}
                                                    span.attachment-download
                                                        span(class='fi fi-rr-download')

                            if reponses_list && reponses_list.length
                                each r in reponses_list
                                    - var role = (r.role || '').toString().toLowerCase();
                                    - var cls = (/admin|accomp/).test(role) ? 'message-admin' : 'message-visiteur';
                                    - var author = r.author_name || (r.user_first_name ? (r.user_first_name + ' ' + (r.user_last_name||'')) : (r.user_name || r.author || ''));
                                    - var dateR = r.created_at ? (new Date(r.created_at)).toLocaleString() : '';
                                    - var fullClass = 'message ' + cls
                                    div&attributes({ 'class': fullClass })
                                        .meta
                                            span.author #{author}
                                            span.date #{dateR}
                                        .body
                                            | #{r.content || r.message || r.body || r.text || ''}
                                        - var attachments = r.attachments || r.files || r.pieces || r.documents || []
                                        if attachments && attachments.length
                                            .attachments
                                                each a in attachments
                                                    - var fileUrl = a.file_url || a.url || a.path || ''
                                                    - var hrefR = ''
                                                    - if(fileUrl && fileUrl.indexOf('/uploads') === 0) hrefR = (backend? backend.replace(/\/$/,'') + fileUrl : fileUrl)
                                                    - else if(fileUrl && /^https?:\/\//.test(fileUrl)) hrefR = fileUrl
                                                    - else if(a.id) hrefR = '/assistances/' + (assist && assist.id ? assist.id : '') + '/reponses/attachments/' + a.id
                                                    - else hrefR = (fileUrl || '#')
                                                    a.attachment(href=hrefR target="_blank" download data-download="1")
                                                        span.file-icon
                                                            span(class='fi fi-rr-file')
                                                        span.attachment-name #{a.filename || a.originalname || a.name || (fileUrl? fileUrl.split('/').pop() : '') || 'Pièce jointe'}
                                                        span.attachment-download
                                                            span(class='fi fi-rr-download')
                        // end messages

                        .composer-wrap(class=(assistClosed ? 'disabled' : ''), style="display:block; position:relative;")
                            // overlay (used by CSS/JS to block interactions when statut final)
                            div.composer-overlay(style=(assistClosed || (statutCode && (''+statutCode).indexOf('term') !== -1 || (statutCode && (''+statutCode).indexOf('refus') !== -1) ? 'display:block;' : 'display:none;'))
                            .selected-files#selectedFiles(style=(assistClosed ? "display:none;" : "display:block;"))
                            if assistClosed
                                .closed-note Assistance clôturée. Vous ne pouvez plus répondre.

                            // form: keep textarea flexible and actions on same line without wrapping
                            form#replyForm(enctype="multipart/form-data" style="display:flex; gap:8px; align-items:center; flex-wrap:nowrap;")
                                - var taStyle = assistClosed ? "flex:1 1 auto; min-height:48px; margin:0; background:#f3f4f6; cursor:not-allowed; color:rgba(0,0,0,0.65); min-width:0;" : "flex:1 1 auto; min-height:48px; margin:0; min-width:0;"
                                textarea#replyContent(name="content" rows="3" placeholder="Écrivez votre message..." style=taStyle disabled=assistClosed)
                                .composer-actions(style="display:flex; gap:8px; align-items:center; flex:0 0 auto; white-space:nowrap;")
                                    - var attachStyle = assistClosed ? 'display:inline-flex; align-items:center; justify-content:center; cursor:not-allowed; padding:6px; border-radius:8px; border:1px solid rgba(11,20,44,0.06); background:#fff; pointer-events:none; opacity:0.6;' : 'display:inline-flex; align-items:center; justify-content:center; cursor:pointer; padding:6px; border-radius:8px; border:1px solid rgba(11,20,44,0.06); background:#fff;'
                                    label.attachment-btn(class=(assistClosed ? 'disabled' : ''), style=attachStyle)
                                        input(type="file" id="attachmentInput" name="attachments" multiple disabled=assistClosed)
                                        span.fi.fi-rr-clip
                                    - var sendStyle = assistClosed ? 'display:inline-flex; align-items:center; padding:8px 12px; border-radius:8px; background:#1E88E5; color:#fff; border:none; opacity:0.6; cursor:not-allowed; pointer-events:none;' : 'display:inline-flex; align-items:center; padding:8px 12px; border-radius:8px; background:#1E88E5; color:#fff; border:none;'
                                    button.send-btn(class=(assistClosed ? 'disabled' : ''), type="submit" style=sendStyle disabled=assistClosed)
                                        span.fi.fi-rr-paper-plane

                            // Immediate defensive script: ensure composer controls are disabled as soon as possible when server indicated closed (or header shows closed)
                            script.
                                (function(){
                                    try{
                                        var page = document.querySelector('.response-page'); if(!page) return;
                                        var assistClosedAttr = page.getAttribute('data-assist-closed') === '1';
                                        var badge = document.getElementById('headerStatusBadge') || document.querySelector('.status-badge');
                                        var badgeText = '';
                                        try{ badgeText = badge && badge.textContent ? (badge.textContent.normalize ? badge.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase() : badge.textContent.toLowerCase()) : ''; }catch(_){ badgeText = (badge && badge.textContent) ? String(badge.textContent).toLowerCase() : ''; }
                                        var closedKeywords = ['termine','terminee','terminé','terminée','refuse','refusee','refus','refusée','cloturee','cloture','clos','closed','rejet','annulee','annule','rejected'];
                                        var badgeIndicatesClosed = closedKeywords.some(function(k){ return (badgeText || '').indexOf(k) !== -1; });
                                        if(!assistClosedAttr && !badgeIndicatesClosed) return;
                                        var wrap = document.querySelector('.composer-wrap'); if(!wrap) return;
                                        try{ wrap.classList.add('disabled'); }catch(_){ }
                                        try{ var ta = wrap.querySelector('textarea#replyContent'); if(ta){ ta.disabled = true; ta.readOnly = true; ta.setAttribute('aria-disabled','true'); } }catch(_){ }
                                        try{ var fi = wrap.querySelector('#attachmentInput'); if(fi){ fi.disabled = true; fi.setAttribute('aria-disabled','true'); } }catch(_){ }
                                        try{ var sb = wrap.querySelector('button.send-btn'); if(sb){ sb.disabled = true; sb.setAttribute('aria-disabled','true'); sb.classList.add('disabled'); } }catch(_){ }
                                        if(!wrap.querySelector('.closed-note')){ var note = document.createElement('div'); note.className = 'closed-note'; note.textContent = 'Assistance clôturée. Vous ne pouvez plus répondre.'; var formEl = wrap.querySelector('form'); if(formEl) wrap.insertBefore(note, formEl); else wrap.appendChild(note); }
                                    }catch(e){ /* noop */ }
                                })();

                            // Client-side attachment preview/render (shows file chip above textarea)
                            script.
                                (function(){
                                    try{
                                        var fileInput = document.getElementById('attachmentInput');
                                        var selectedWrap = document.getElementById('selectedFiles');
                                        if(!fileInput || !selectedWrap) return;

                                        // DataTransfer to manage files so input.files can be mutated
                                        var dt = new DataTransfer();

                                        function renderChips(){
                                            selectedWrap.innerHTML = '';
                                            Array.from(dt.files).forEach(function(f, idx){
                                                var chip = document.createElement('div');
                                                chip.className = 'file-chip';
                                                chip.style.display = 'flex';
                                                chip.style.alignItems = 'center';
                                                chip.style.justifyContent = 'space-between';
                                                chip.style.gap = '12px';
                                                chip.style.padding = '8px 12px';
                                                chip.style.background = '#eef6ff';
                                                chip.style.borderRadius = '12px';

                                                var left = document.createElement('div');
                                                left.style.display = 'flex';
                                                left.style.alignItems = 'center';
                                                left.style.gap = '10px';

                                                var ico = document.createElement('span'); ico.className = 'file-icon'; ico.textContent = ''; ico.style.fontSize = '16px';
                                                var name = document.createElement('span'); name.className = 'file-name'; name.textContent = f.name; name.style.overflow = 'hidden'; name.style.textOverflow = 'ellipsis'; name.style.whiteSpace = 'nowrap'; name.style.maxWidth = '240px';
                                                left.appendChild(ico); left.appendChild(name);

                                                var actions = document.createElement('div'); actions.style.display = 'flex'; actions.style.alignItems = 'center'; actions.style.gap = '8px';

                                                var dl = document.createElement('a'); dl.className = 'attachment-download'; dl.textContent = '⬇️'; dl.href = '#'; dl.style.textDecoration = 'none'; dl.style.color = '#095ab5'; dl.style.fontSize = '16px'; dl.target = '_blank';
                                                try{
                                                    var blobUrl = URL.createObjectURL(f);
                                                    dl.href = blobUrl; dl.download = f.name;
                                                    dl.addEventListener('click', function(){ setTimeout(function(){ try{ URL.revokeObjectURL(blobUrl); }catch(_){ } }, 2000); });
                                                }catch(_){ }

                                                var removeBtn = document.createElement('button'); removeBtn.type = 'button'; removeBtn.className = 'file-remove'; removeBtn.textContent = '×'; removeBtn.style.background = 'none'; removeBtn.style.border = 'none'; removeBtn.style.color = '#095ab5'; removeBtn.style.cursor = 'pointer'; removeBtn.style.fontSize = '16px';
                                                removeBtn.addEventListener('click', function(){
                                                    var newDt = new DataTransfer();
                                                    Array.from(dt.files).forEach(function(ff, i){ if(i !== idx) newDt.items.add(ff); });
                                                    dt = newDt; fileInput.files = dt.files; renderChips();
                                                });

                                                actions.appendChild(dl); actions.appendChild(removeBtn);

                                                chip.appendChild(left); chip.appendChild(actions);
                                                selectedWrap.appendChild(chip);
                                            });

                                            selectedWrap.style.display = (dt.files && dt.files.length) ? 'block' : 'none';
                                        }

                                        fileInput.addEventListener('change', function(e){
                                            var incoming = Array.from(fileInput.files || []);
                                            incoming.forEach(function(f){
                                                var exists = Array.from(dt.files).some(function(x){ return x.name === f.name && x.size === f.size && x.lastModified === f.lastModified; });
                                                if(!exists) dt.items.add(f);
                                            });
                                            fileInput.files = dt.files; renderChips();
                                        });

                                        // keep chips in sync when form reset occurs
                                        var form = document.getElementById('replyForm');
                                        if(form){
                                            form.addEventListener('reset', function(){ dt = new DataTransfer(); fileInput.files = dt.files; renderChips(); });
                                        }

                                        // initial render (in case preloaded files exist)
                                        renderChips();
                                    }catch(e){ console.error('attachment preview init error', e); }
                                })();

                            // Intercept clicks on server-side attachment anchors and download via fetch with credentials
                            script.
                                (function(){
                                    try{
                                        document.addEventListener('click', function(ev){
                                            var a = ev.target.closest && ev.target.closest('.attachment');
                                            if(!a) return;
                                            var href = a.getAttribute('href') || '';
                                            // if href is a blob or local url (starts with blob: or data:) let browser handle it
                                            if(!href || href === '#' || href.indexOf('blob:') === 0 || href.indexOf('data:') === 0) return;
                                            // Only intercept backend proxied attachment endpoints or paths that look like /assistances/.../attachments/ or /uploads
                                            if(!(href.indexOf('/reponses/attachments/') !== -1 || href.indexOf('/assistances/') === 0 || href.indexOf('/uploads') === 0 || href.indexOf(location.origin) === 0)) return;
                                            ev.preventDefault();
                                            a.classList.add('attachment-loading');
                                            (async function(){
                                                try{
                                                    var resp = await fetch(href, { credentials: 'include' });
                                                    if(!resp.ok){
                                                        var txt = await resp.text().catch(function(){ return 'HTTP ' + resp.status; });
                                                        alert('Erreur téléchargement: ' + resp.status + '\n' + txt);
                                                        return;
                                                    }
                                                    var blob = await resp.blob();
                                                    var filename = (a.querySelector('.attachment-name') && a.querySelector('.attachment-name').textContent.trim()) || 'download';
                                                    try{
                                                        var cd = resp.headers.get('content-disposition');
                                                        if(cd){ var m = cd.match(/filename\*?=(?:UTF-8'')?"?([^;"']+)"?/i); if(m && m[1]) filename = decodeURIComponent(m[1]); }
                                                    }catch(_){ }
                                                    var blobUrl = URL.createObjectURL(blob);
                                                    var tmp = document.createElement('a'); tmp.href = blobUrl; tmp.download = filename; document.body.appendChild(tmp); tmp.click(); tmp.remove(); setTimeout(function(){ try{ URL.revokeObjectURL(blobUrl); }catch(_){ } }, 2000);
                                                }catch(e){ console.error('attachment download error', e); alert('Erreur réseau lors du téléchargement'); }
                                                finally{ try{ a.classList.remove('attachment-loading'); }catch(_){ } }
                                            })();
                                        });
                                    }catch(e){ console.error('attachment download interceptor init error', e); }
                                })();

                            // Intercept form submit and send message + attachments via fetch
                            script.
                                (function(){
                                    try{
                                        var page = document.querySelector('.response-page');
                                        var form = document.getElementById('replyForm');
                                        if(!page || !form) return;
                                        var assistId = page.getAttribute('data-assist-id') || '';
                                        form.addEventListener('submit', async function(ev){
                                            ev.preventDefault();
                                            try{
                                                var submitBtn = form.querySelector('button[type="submit"]');
                                                if(submitBtn) submitBtn.disabled = true;
                                                var ta = form.querySelector('textarea[name="content"]');
                                                var content = ta ? String(ta.value || '').trim() : '';
                                                var fileInput = form.querySelector('#attachmentInput');
                                                var hasFiles = fileInput && fileInput.files && fileInput.files.length;
                                                if(!content && !hasFiles){ alert('Veuillez saisir un message ou joindre un fichier.'); if(submitBtn) submitBtn.disabled = false; return; }

                                                var fd = new FormData();
                                                fd.append('content', content);
                                                if(fileInput && fileInput.files){
                                                    for(var i=0;i<fileInput.files.length;i++){ fd.append('attachments', fileInput.files[i]); }
                                                }
                                                // role for server: visitor
                                                fd.append('role', 'visiteur');

                                                var url = '/assistances/' + encodeURIComponent(assistId) + '/reponses';

                                                var resp = await fetch(url, { method: 'POST', body: fd, credentials: 'include' });
                                                if(!resp.ok){
                                                    var txt = '';
                                                    try{ txt = await resp.text(); }catch(_){ txt = String(resp.status); }
                                                    alert('Erreur envoi: ' + resp.status + '\n' + txt);
                                                    return;
                                                }

                                                // success: clear form & selected files preview and reload to get latest messages
                                                try{ form.reset(); }catch(_){ }
                                                try{ var evc = new Event('change'); var fi = form.querySelector('#attachmentInput'); if(fi) fi.dispatchEvent(evc); }catch(_){ }
                                                // reload to show the freshly posted message
                                                location.reload();
                                            }catch(e){ console.error('reply submit error', e); alert('Erreur réseau lors de l\'envoi'); }
                                            finally{ try{ var b = form.querySelector('button[type="submit"]'); if(b) b.disabled = false; }catch(_){ } }
                                        });
                                    }catch(e){ console.error('reply init error', e); }
                                })();

                            // Immediately check badge and disable composer if final
                            script.
                                (function(){
                                    try{
                                        var b = document.getElementById('headerStatusBadge');
                                        if(!b) return;
                                        var txt = (b.textContent||'').toString();
                                        try{ txt = txt.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(); }catch(_){ txt = txt.toLowerCase(); }
                                        console.debug('[reponse] headerStatusBadge text=', txt);
                                        if(!txt) return;
                                        if(txt.indexOf('term') !== -1 || txt.indexOf('refus') !== -1){
+                                            // mark page so CSS can apply (works even if data-statut missing)
+                                            try{ var page = document.querySelector('.response-page'); if(page) page.classList.add('statut-final'); }catch(_){ }
                                            try{
                                                var wrap = document.querySelector('.composer-wrap');
                                                if(wrap){
                                                    wrap.classList.add('disabled');
                                                    var ta = wrap.querySelector('textarea#replyContent'); if(ta){ ta.disabled = true; ta.readOnly = true; ta.setAttribute('aria-disabled','true'); }
                                                    var fi = wrap.querySelector('#attachmentInput'); if(fi){ fi.disabled = true; fi.setAttribute('aria-disabled','true'); }
                                                    var btn = wrap.querySelector('button.send-btn'); if(btn){ btn.disabled=true; btn.setAttribute('aria-disabled','true'); btn.classList.add('disabled'); }
                                                }
                                            }catch(_){ }
                                        }
                                    }catch(e){/*noop*/}
                                })();
